22	export function nextGeneration(cells: Cell[]): Cell[] {
23	  const aliveKeys = new Set(cells.map(cellKey));
24	  const isAlive = (cell: Cell): boolean => aliveKeys.has(cellKey(cell));
25	  const aliveNeighborCount = (cell: Cell): number =>
26	    neighborsOf(cell).filter(isAlive).length;
27	
28	  const candidates = uniqueCells([...cells, ...cells.flatMap(neighborsOf)]);
29	
30	  return candidates.filter((cell) => {
31	    const neighbors = aliveNeighborCount(cell);
32	    return isAlive(cell)
33	      ? survivesWithNeighborCount(neighbors)
34	      : isBornWithNeighborCount(neighbors);
35	  });
36	}
